cd /app && python3 -c "import pandas as pd, numpy as np; from scipy.stats import norm; from scipy.optimize import minimize; c=pd.read_csv('data/conversions.csv'); d=c.delay_hours.values; print('n',len(d),'eq72',(d>=72.0).sum(),'ge71.9',(d>=71.9).sum()); L=np.log(d); print('plain mu,sig',L.mean(),L.std()); cen=d>=72.0; ld=L[~cen]; lc=np.log(72.0)
def nll(p):
    mu,ls=p; s=np.exp(ls)
    obs=norm.logpdf(ld,mu,s).sum(); ce=norm.logsf(lc,mu,s)*cen.sum()
    return -(obs+ce)
r=minimize(nll,[L.mean(),np.log(L.std())],method='Nelder-Mead'); print('censored mu,sig',r.x[0],np.exp(r.x[1]))"
